+  memcpy(assoc_parsed.bssid, whdr->bssid.data, 6);
+  memcpy(assoc_parsed.sa, whdr->src.data, 6);
+  memcpy(assoc_parsed.da, whdr->dst.data, 6);
+
+  Dot11DecryptScanFtAssocForKeys(&dot11decrypt_ctx, &assoc_parsed);
